-- Semilla de composicion de desayunos para Supabase.
-- Ejecutar despues de sql/menu_catalog_supabase.sql.

on conflict (category_id, menu_legacy_id, item_group, name) do update set
  legacy_id = excluded.legacy_id,
  quantity_type = excluded.quantity_type,
  quantity = excluded.quantity,
  divisor = excluded.divisor,
  unit = excluded.unit,
  quantity_per_pax = excluded.quantity_per_pax,
  selector_termo = excluded.selector_termo,
  options = excluded.options,
  pulguitas = excluded.pulguitas,
  fixed_flavor = excluded.fixed_flavor,
  sandwiches_count = excluded.sandwiches_count,
  display_order = excluded.display_order,
  active = excluded.active,
  updated_at = now();
